/**
 * Seed = replay.
 *
 * 30 days of history are generated by running the REAL commands (PlaceOrder,
 * the worker, payments, refunds, reviews, verifications, catalog syncs…) on a
 * simulated clock. Every order therefore has a consistent account, price
 * snapshot, supplier attempts, timeline, ledger postings, notifications,
 * webhooks and API logs — nothing is fabricated table-by-table.
 *
 * At the end, the scenarios A–L are scripted with targeted simulator rules,
 * a few balances are calibrated to the demo script, and the clock switches to
 * live time so in-flight orders keep moving.
 */
import { formatMoney, roundTo, times, usd, type Micros } from '@/core/money'
import { SYSTEM, type Actor, type FieldDef, type OrderChannel, type PaymentMethodKind } from '@/core/domain'
import { withLuhn, GSM_BRANDS } from '@/core/verticals/gsm'
import { placeOrder, refundOrder } from '@/core/commands/orders'
import { completePayment, confirmBankTransfer, createTopUp, openChargeback, replayGatewayWebhook } from '@/core/commands/payments'
import { confirmNotReceived, lookupSupplier } from '@/core/commands/review'
import { approveVerificationRefund, openVerification, rejectVerification, requestSupplierVerification } from '@/core/commands/verification'
import { decideSyncChanges, setMaintenance, updateCredentials } from '@/core/commands/suppliers'
import { adjustAccountWallet, ensureGuestAccount, setAccountStatus } from '@/core/commands/accounts'
import { addOffer, setServicePrice, upsertPricingRule } from '@/core/commands/catalog'
import { createApiKey } from '@/core/commands/developer'
import { runSync } from '@/core/services/catalogSync'
import { supplierTopUp, walletBalance } from '@/core/services/ledger'
import { quote } from '@/core/services/pricing'
import { availability } from '@/core/services/routing'
import { supplierDrift } from '@/core/services/supplier'
import { audit } from '@/core/services/audit'
import { notify } from '@/core/services/notifications'
import { DomainError } from '@/core/errors'
import { createRng } from '@/lib/random'
import { runJobs, type Runtime, type ScenarioRef } from './runtime'
import { remoteOf } from './sim/drivers'
import { setBehaviour, type SimBehaviour } from './sim/simulator'
import { DEMO_IMEIS } from './sim/results'
import { handleNative } from './api/native'
import { handleDhru } from './api/dhru'
import { SUPPLIER_SPECS, buildSupplier } from './data/suppliers'
import { POPULARITY, buildCatalog } from './data/catalog'
import { TIERS, buildRules } from './data/pricing'
import { ACCOUNT_SPECS, buildAccount, buildMembers, retailSpecs, type AccountSpec } from './data/accounts'
import { NOTIFICATION_CHANNELS, NOTIFICATION_ROUTES, PAYMENT_METHODS, ROLES, buildApiKeys, buildUsers, buildWebhookEndpoints } from './data/system'
import { buildStorefront } from './data/storefront'
import { buildSystemState } from './data/systemState'
import { GLOBAL_CATALOG, GLOBAL_PROVIDER_SPEC, GLOBAL_SYNC_DELTA, toRemoteProduct } from './data/providerCatalog'

/** A client IP that satisfies the key's allow-list (first rule), if any. */
const ipFor = (key: { ipAllowlist: string[] }) => key.ipAllowlist[0]?.replace(/\/\d+$/, '').replace(/\.0$/, '.14')

const MIN = 60_000
const HOUR = 3600_000
const DAY = 86400_000
const HOUR_WEIGHTS = [1.2, 0.8, 0.6, 0.5, 0.5, 0.8, 1.5, 3, 5, 6.5, 7, 7.5, 7, 7, 7.5, 7.5, 7, 6, 5, 4.2, 3.6, 3, 2.4, 1.6]

const GUEST_EMAILS = ['j.romero@mail.example', 'k.tanaka@mail.example', 'phonebuyer88@mail.example', 'a.nowak@mail.example', 'trade.ins@mail.example', 'm.ferreira@mail.example', 'oliver.p@mail.example', 'leila.k@mail.example', 'sam.t@mail.example', 'ines.v@mail.example', 'h.akbar@mail.example', 'claire.d@mail.example']

type Kind = 'order' | 'poll' | 'read' | 'error' | 'sweep' | 'action'
interface PlanItem {
  t: number
  kind: Kind
  accountId?: string
  channel?: OrderChannel
  serviceId?: string
  run?: () => void
}

export function seedRuntime(rt: Runtime, now: number) {
  const { repo, ctx, clock, rng } = rt
  const t0 = now - 30 * DAY
  clock.set(t0 - HOUR)

  /* ---------------- 1. Base data ---------------- */
  for (const spec of SUPPLIER_SPECS) repo.suppliers.insert(buildSupplier(spec, now))
  const cat = buildCatalog(now)
  cat.categories.forEach((c) => repo.categories.insert(c))
  cat.services.forEach((s) => repo.services.insert(s))
  cat.revisions.forEach((r) => repo.revisions.insert(r))
  cat.products.forEach((p) => repo.products.insert(p))
  cat.offers.forEach((o) => repo.offers.insert(o))
  // Scenario F: Gamma's Motorola IMEI Check used to cost $0.38 (raised six days ago).
  const motoProduct = repo.products.require('sp_gamma_4011')
  motoProduct.cost = usd(0.38)
  TIERS.forEach((t) => repo.tiers.insert(t))
  buildRules(now).forEach((r) => repo.rules.insert(r))
  const allSpecs: AccountSpec[] = [...ACCOUNT_SPECS, ...retailSpecs()]
  allSpecs.forEach((spec, i) => {
    const a = buildAccount(spec, now, i + 1)
    a.createdAt = new Date(Math.min(new Date(a.createdAt).getTime(), t0 - DAY)).toISOString()
    if (spec.id === 'acc_unlockzone' || spec.id === 'acc_r18') {
      a.status = 'active'
      a.statusReason = null
    }
    repo.accounts.insert(a)
    buildMembers(spec, now).forEach((m) => repo.members.insert(m))
  })
  ROLES.forEach((r) => repo.roles.insert(r))
  buildUsers(now).forEach((u) => repo.users.insert(u))
  PAYMENT_METHODS.forEach((m) => repo.paymentMethods.insert(m))
  NOTIFICATION_CHANNELS.forEach((c) => repo.notificationChannels.insert(c))
  NOTIFICATION_ROUTES.forEach((r) => repo.notificationRoutes.insert(r))
  buildWebhookEndpoints(now).forEach((w) => repo.webhookEndpoints.insert(w))
  buildApiKeys(now).forEach((k) => repo.apiKeys.insert(k))
  repo.storefront.set(buildStorefront(now, ctx.ids))
  rt.system = buildSystemState(now)

  for (const s of repo.suppliers.all()) {
    const remote = remoteOf(rt.env, s.id)
    remote.balance = usd(1_000_000)
    remote.catalog = repo.products.filter((p) => p.supplierId === s.id).map((p) => ({ externalId: p.externalId, name: p.name, groupName: p.groupName, cost: p.cost, fields: [...p.remoteFields], processingHint: p.processingHint }))
  }

  /* ---------------- helpers ---------------- */
  const admin = (id: string): Actor => {
    const u = repo.users.require(id)
    return { type: 'admin', id: u.id, name: u.name, role: repo.roles.get(u.roleId)?.name }
  }
  const SARAH = admin('usr_sarah')
  const DANIEL = admin('usr_daniel')
  const OMAR = admin('usr_omar')
  const ALEX = admin('usr_alex')
  const memberOf = (accountId: string, prefer: string[] = ['orderer', 'owner']): Actor => {
    const ms = repo.members.filter((m) => m.accountId === accountId)
    const m = prefer.map((r) => ms.find((x) => x.role === r)).find(Boolean) ?? ms[0]!
    return { type: 'member', id: m.id, name: `${m.name} (${repo.accounts.get(accountId)?.name})`, role: m.role }
  }
  const keyOf = (accountId: string) => repo.apiKeys.find((k) => k.accountId === accountId && k.status === 'active' && k.environment === 'live')
  const dhruKeyOf = (accountId: string) => repo.apiKeys.find((k) => k.accountId === accountId && k.status === 'active' && k.dhruCompat)
  const at = (t: number) => clock.set(t)
  const safely = <T>(f: () => T): T | null => {
    try {
      return f()
    } catch (e) {
      if (e instanceof DomainError) return null
      throw e
    }
  }

  const randomImei = () => withLuhn(`${rng.pick(['35', '35', '35', '86', '01', '49'])}${String(rng.int(100000, 999999))}${String(rng.int(100000, 999999))}`)
  const inputFor = (fields: FieldDef[], imei?: string): Record<string, string> => {
    const out: Record<string, string> = {}
    for (const f of fields) {
      if (!f.required && rng.bool(0.5)) continue
      switch (f.type) {
        case 'gsm.imei':
          out[f.key] = imei ?? randomImei()
          break
        case 'gsm.serial':
          out[f.key] = `${rng.pick(['F2L', 'DX3', 'G6T', 'C39', 'R58', 'HN7'])}${rng.hex(5).toUpperCase()}${rng.int(1000, 9999)}`.slice(0, 12)
          break
        case 'gsm.brand':
          out[f.key] = rng.pick(GSM_BRANDS.slice(0, 7)).value
          break
        case 'gsm.model':
          out[f.key] = rng.pick(['iPhone 15', 'iPhone 14 Pro', 'SM-S911B', 'SM-A546B', 'Pixel 8', 'Moto G84', 'Redmi Note 13', 'E5577s-321', 'TCL 30 SE', 'ZTE Blade A52'])
          break
        case 'gsm.carrier':
          out[f.key] = rng.pick(f.options ?? [{ value: 'tmobile_us', label: '' }]).value
          break
        case 'country':
          out[f.key] = rng.pick(['US', 'GB', 'DE', 'FR', 'AE', 'ES', 'TR', 'CA'])
          break
        default:
          out[f.key] = 'demo'
      }
    }
    return out
  }
  const fieldsOf = (serviceId: string) => repo.revisions.require(repo.services.require(serviceId).revisionId).fields

  const accountSpec = new Map(allSpecs.map((s) => [s.id, s]))
  /** Resellers and businesses top up their wallet before they run dry. */
  const autoTopUp = (accountId: string, needed: Micros) => {
    const spec = accountSpec.get(accountId)
    const acct = repo.accounts.require(accountId)
    if (acct.tier === 'retail' || acct.kind === 'guest') return
    const bal = walletBalance(ctx, accountId)
    if (bal.spendable >= needed) return
    const small = spec?.targetAvailable != null && spec.targetAvailable < 100
    const base = small ? rng.pick([25, 30, 50]) : accountId === 'acc_abcgsm' ? rng.pick([100, 150]) : Math.max(100, Math.round((spec?.weight ?? 3) * rng.float(40, 90) / 50) * 50)
    const amount = usd(base + Math.ceil((needed - bal.spendable) / 1_000_000))
    const method: PaymentMethodKind = accountId === 'acc_unlockzone' ? 'card' : base >= 500 ? 'bank_transfer' : rng.pick(['card', 'card', 'bank_transfer'])
    const intent = createTopUp(ctx, { accountId, amount, method, actor: memberOf(accountId, ['finance', 'owner']) })
    if (method === 'bank_transfer') confirmBankTransfer(ctx, { intentId: intent.id, actor: OMAR })
    else completePayment(ctx, { intentId: intent.id, outcome: 'succeed' })
  }

  /* ---------------- 2. Placement plan ---------------- */
  const plan: PlanItem[] = []
  const push = (it: PlanItem) => {
    let i = plan.length
    while (i > 0 && plan[i - 1]!.t > it.t) i--
    plan.splice(i, 0, it)
  }
  const byChannel = (ch: 'portal' | 'api' | 'dhru') => allSpecs.filter((s) => s.channels.includes(ch) && s.weight > 0 && s.tier !== 'retail')
  const retail = allSpecs.filter((s) => s.tier === 'retail')
  const activeServices = repo.services.filter((s) => s.status === 'active')
  const THETA_SERVICES = new Set(['svc_4017', 'svc_4021'])
  const ETA_SERVICES = new Set(['svc_4041', 'svc_4050', 'svc_4042'])

  const pickService = (accountId: string, channel: OrderChannel, t: number) => {
    const acct = repo.accounts.require(accountId)
    let pool = activeServices.filter((s) => {
      if (channel === 'storefront' && !s.visibility.storefront) return false
      const a = acct.serviceAccess
      if (a.mode === 'categories' && !a.categoryIds.includes(s.categoryId)) return false
      if (accountId === 'acc_abcgsm' && s.processing !== 'instant') return false
      if (THETA_SERVICES.has(s.id) && t > now - 50 * MIN) return false
      if (ETA_SERVICES.has(s.id) && t > now - 25 * MIN) return false
      if (s.id === 'svc_4042' && t > now - 2 * HOUR) return false
      return true
    })
    if (!pool.length) pool = activeServices
    return rng.weighted(pool, pool.map((s) => Math.max(0.4, POPULARITY[s.id] ?? 1))).id
  }

  for (let d = 29; d >= 0; d--) {
    const day = new Date(now - d * DAY)
    day.setHours(0, 0, 0, 0)
    const weekend = day.getDay() === 0 || day.getDay() === 6
    const count = Math.round((weekend ? 27 : 42) * (0.78 + 0.4 * ((29 - d) / 29)) * rng.float(0.85, 1.15))
    for (let i = 0; i < count; i++) {
      const hour = rng.weighted(HOUR_WEIGHTS.map((_, h) => h), HOUR_WEIGHTS)
      const t = day.getTime() + hour * HOUR + rng.int(0, HOUR - 1)
      if (t < t0 || t > now - 3 * MIN) continue
      const channel = rng.weighted(['storefront', 'portal', 'api', 'dhru', 'admin'] as const, [26, 21, 38, 13, 2])
      let accountId: string
      if (channel === 'storefront') accountId = rng.bool(0.42) ? `guest:${rng.pick(GUEST_EMAILS)}` : rng.pick(retail).id
      else if (channel === 'admin') accountId = rng.pick(byChannel('portal')).id
      else {
        const pool = byChannel(channel)
        accountId = rng.weighted(pool, pool.map((s) => s.weight)).id
      }
      if (accountId === 'acc_abcgsm' && t > now - 2 * HOUR) continue
      if (accountId === 'acc_unlockzone' && t > now - 3 * DAY) continue
      if (accountId === 'acc_r18' && t > now - 2 * DAY) continue
      push({ t, kind: 'order', accountId, channel })
    }
  }
  // Catalog / balance reads and a sprinkling of client errors on the APIs.
  for (let i = 0; i < 140; i++) push({ t: now - rng.int(5 * MIN, 29 * DAY), kind: 'read' })
  for (let i = 0; i < 45; i++) push({ t: now - rng.int(5 * MIN, 29 * DAY), kind: 'error' })
  // Operator sweeps: resolve reviews that were opened long enough ago.
  for (let t = t0 + 3 * HOUR; t < now - 6 * HOUR; t += 3 * HOUR) push({ t, kind: 'sweep' })

  /* ---------------- 3. Timeline actions (operators, suppliers, finance) ---------------- */
  const action = (msAgo: number, run: () => void) => push({ t: now - msAgo, kind: 'action', run })

  // Periodic catalog syncs (no changes) for every supplier.
  for (const s of SUPPLIER_SPECS) for (let k = 0; k < 4; k++) action(rng.int(1, 28) * DAY + rng.int(0, 20) * HOUR, () => runSync(ctx, s.id, SYSTEM, 'scheduled'))
  // Admin history (audited through real commands).
  action(33 * DAY, () => audit(ctx, { actor: ALEX, action: 'role.changed', target: { type: 'user', id: 'usr_daniel', label: 'Daniel Okafor' }, summary: 'Changed role Support → Operations', severity: 'notice', permission: 'roles.manage', changes: [{ field: 'role', from: 'Support', to: 'Operations' }] }))
  action(21 * DAY, () => setServicePrice(ctx, { serviceId: 'svc_4001', tierId: 'tier_platinum', amount: usd(0.82), reason: 'Contract renewal — MobileHub & TechRepair Pro', actor: SARAH }))
  action(20 * DAY, () => updateCredentials(ctx, { supplierId: 'sup_alpha', credentials: [{ key: 'api_access_key', value: 'K7Q2-NEWKEY-2026-91XZ' }], actor: SARAH }))
  action(18 * DAY, () => setServicePrice(ctx, { serviceId: 'svc_4006', tierId: 'tier_gold', amount: usd(0.15), reason: 'Volume price for trade-in resellers', actor: OMAR }))
  action(14 * DAY, () => upsertPricingRule(ctx, { ruleId: 'prl_silver_unlock', rule: { tierId: 'tier_silver', scope: { kind: 'category', categoryId: 'cat_unlock' }, method: 'cost_plus_percent', value: 2000, rounding: { increment: usd(0.05), mode: 'up' }, minMarginBps: null, enabled: true, note: 'Unlock codes rounded to 5 cents' }, reason: 'Round unlock prices to 5 cents', actor: OMAR }))
  action(12 * DAY, () => createApiKey(ctx, { accountId: 'acc_repairdesk', name: 'Connector v2', environment: 'live', scopes: ['services:read', 'orders:read', 'orders:write', 'account:read'], ipAllowlist: [], rateLimitPerMin: 600, dhruCompat: false, expiresInDays: 365, actor: SARAH }))
  action(9 * DAY, () => audit(ctx, { actor: ALEX, action: 'role.changed', target: { type: 'user', id: 'usr_priya', label: 'Priya Raman' }, summary: 'Changed role Viewer → Support', severity: 'notice', permission: 'roles.manage', changes: [{ field: 'role', from: 'Viewer', to: 'Support' }] }))
  // Scenario F: Gamma raises its Motorola IMEI Check cost; Sarah applies it 25 minutes later.
  let gammaRun: string | null = null
  action(6 * DAY, () => {
    const r = remoteOf(rt.env, 'sup_gamma')
    const p = r.catalog.find((x) => x.externalId === motoProduct.externalId)
    if (p) p.cost = usd(0.46)
    gammaRun = runSync(ctx, 'sup_gamma', SYSTEM, 'scheduled').id
  })
  action(6 * DAY - 25 * MIN, () => {
    const change = repo.syncChanges.find((c) => c.runId === gammaRun && c.kind === 'price')
    if (change) decideSyncChanges(ctx, { changeIds: [change.id], decision: 'applied', actor: SARAH })
  })
  // UnlockZone: two card chargebacks, then frozen by finance.
  const chargeback = (reason: string) => {
    const intent = repo.payments.find((p) => p.accountId === 'acc_unlockzone' && p.method === 'card' && p.status === 'succeeded' && !p.chargebackId)
    if (intent) openChargeback(ctx, { intentId: intent.id, reason })
  }
  action(5 * DAY, () => chargeback('Cardholder does not recognise the transaction'))
  action(3 * DAY + 2 * HOUR, () => chargeback('Fraudulent — card reported stolen'))
  action(3 * DAY, () => setAccountStatus(ctx, { accountId: 'acc_unlockzone', status: 'frozen', reason: 'Two card chargebacks on wallet top-ups — finance review', actor: OMAR }))
  action(2 * DAY, () => setAccountStatus(ctx, { accountId: 'acc_r18', status: 'frozen', reason: 'Card used in a fraud report — awaiting verification', actor: SARAH }))
  // Historical refunds and after-care.
  for (const [d, dest, who] of [[24, 'wallet', OMAR], [19, 'original_method', SARAH], [15, 'wallet', OMAR], [11, 'wallet', OMAR], [8, 'original_method', SARAH], [4, 'wallet', OMAR]] as const) {
    action(d * DAY, () => {
      const o = repo.orders.find((x) => x.status === 'completed' && x.financialStatus === 'captured' && (dest === 'original_method' ? x.channel === 'storefront' && !!x.paymentIntentId : x.channel !== 'storefront') && ctx.clock.now() - new Date(x.createdAt).getTime() > DAY)
      if (o) safely(() => refundOrder(ctx, { orderId: o.id, amount: o.price.amount, destination: dest, reason: dest === 'wallet' ? 'Result disputed — supplier confirmed data error' : 'Customer charged twice by their bank — refunded to card', actor: who, idempotencyKey: `seed-refund-${d}` }))
    })
  }
  const verificationStory = (d: number, outcome: 'approve' | 'reject' | 'awaiting') => {
    let vid: string | null = null
    let oid: string | null = null
    action(d * DAY, () => {
      const o = repo.orders.find((x) => x.status === 'completed' && x.financialStatus === 'captured' && repo.services.get(x.serviceId)?.categoryId === 'cat_unlock' && x.verificationIds.length === 0 && ctx.clock.now() - new Date(x.completedAt!).getTime() > 6 * HOUR)
      if (!o) return
      const v = safely(() => openVerification(ctx, { orderId: o.id, reason: 'code_not_working', message: rng.pick(['Code does not work', 'Phone says “Network unlock unsuccessful”', 'Code rejected after entry']), actor: o.channel === 'storefront' ? { type: 'guest', id: o.accountId, name: repo.accounts.get(o.accountId)?.name ?? 'Customer' } : memberOf(o.accountId) }))
      vid = v?.id ?? null
      oid = o.id
    })
    action(d * DAY - 70 * MIN, () => {
      if (!vid) return
      rt.sim.verificationFaulty = outcome === 'approve'
      safely(() => requestSupplierVerification(ctx, { verificationId: vid!, actor: DANIEL }))
    })
    if (outcome === 'awaiting') return
    action(d * DAY - 3 * HOUR, () => {
      if (!vid || !oid) return
      const o = repo.orders.require(oid)
      if (outcome === 'approve') safely(() => approveVerificationRefund(ctx, { verificationId: vid!, amount: (o.price.amount - o.refundedTotal) as Micros, destination: 'wallet', note: 'Supplier confirmed the code was wrong', actor: OMAR }))
      else safely(() => rejectVerification(ctx, { verificationId: vid!, note: 'Supplier re-verified the code; customer entered it with a SIM from the same network. Instructions resent.', actor: DANIEL }))
      rt.sim.verificationFaulty = true
    })
  }
  verificationStory(17, 'approve')
  verificationStory(10, 'reject')
  verificationStory(6, 'approve')
  verificationStory(2, 'reject')
  verificationStory(1, 'awaiting')
  action(4 * HOUR, () => notify(ctx, { template: 'api.error_spike', vars: { message: '4xx rate 6.4% over 5 minutes on POST /v1/orders (mostly validation_failed from one client)' } }))

  /* ---------------- 4. Recent scripted state (suppliers) ---------------- */
  action(2 * HOUR, () => {
    remoteOf(rt.env, 'sup_epsilon').credentialsValid = false
  })
  action(40 * MIN, () => {
    remoteOf(rt.env, 'sup_iota').maintenance = true
    setMaintenance(ctx, { supplierId: 'sup_iota', active: true, until: new Date(now + 80 * MIN).toISOString(), note: 'Supplier maintenance window announced by email', actor: DANIEL })
  })

  /* ---------------- 5. Replay ---------------- */
  const execOrder = (it: PlanItem) => {
    let accountId = it.accountId!
    const channel = it.channel!
    let actor: Actor
    if (accountId.startsWith('guest:')) {
      accountId = ensureGuestAccount(ctx, accountId.slice(6), 'tier_retail').id
      actor = { type: 'guest', id: accountId, name: repo.accounts.get(accountId)!.email }
    } else actor = channel === 'admin' ? rng.pick([SARAH, DANIEL]) : channel === 'storefront' ? { type: 'member', id: accountId, name: repo.accounts.get(accountId)!.name } : memberOf(accountId)
    const acct = repo.accounts.get(accountId)
    if (!acct || acct.status !== 'active') return
    const serviceId = it.serviceId ?? pickService(accountId, channel, it.t)
    const service = repo.services.require(serviceId)
    const input = inputFor(fieldsOf(serviceId))
    const price = quote(ctx, serviceId, acct.pricingTierId).amount
    if (!availability(ctx, service, price).available) return
    if (channel === 'storefront') {
      const method = rng.weighted(['card', 'paypal', 'bank_transfer'] as PaymentMethodKind[], [70, 25, 5])
      const r = safely(() => placeOrder(ctx, { accountId, serviceId, input, channel, actor, payment: { mode: 'external', method }, tracking: true }))
      if (!r || !r.paymentIntentId) return
      const roll = rng.next()
      if (method === 'bank_transfer') {
        ctx.scheduler.schedule('payment.settle', { intentId: r.paymentIntentId, outcome: 'pending' }, it.t + rng.int(60, 300) * 1000)
        ctx.scheduler.schedule('payment.settle', { intentId: r.paymentIntentId, outcome: 'succeed' }, it.t + rng.int(8, 25) * MIN)
      } else if (roll < 0.94) ctx.scheduler.schedule('payment.settle', { intentId: r.paymentIntentId, outcome: 'succeed' }, it.t + rng.int(25, 150) * 1000)
      else if (roll < 0.97) ctx.scheduler.schedule('payment.settle', { intentId: r.paymentIntentId, outcome: 'fail' }, it.t + rng.int(25, 150) * 1000)
      // else: abandoned checkout — expires after 30 minutes
      return
    }
    autoTopUp(accountId, (price * 1.05) as Micros)
    if (channel === 'api') {
      const key = keyOf(accountId)
      if (!key) return
      const idem = rng.bool(0.9) ? `idem_${rng.hex(16)}` : undefined
      const svc = service.code
      handleNative(rt, { method: 'POST', path: '/v1/orders', headers: { authorization: `Bearer ${key.prefix}_${rng.hex(24)}`, ...(idem ? { 'idempotency-key': idem } : {}) }, body: { service: svc, input, client_reference: `${acct.name.slice(0, 3).toUpperCase()}-${rng.int(100000, 999999)}` }, ip: ipFor(key) })
      const placed = repo.orders.recent(1)[0]
      if (placed && placed.accountId === accountId) for (let k = rng.int(0, 2); k > 0; k--) push({ t: it.t + rng.int(4, 180) * 1000, kind: 'poll', accountId, serviceId: placed.ref })
      return
    }
    if (channel === 'dhru') {
      const key = dhruKeyOf(accountId)
      if (!key) return
      const rev = repo.revisions.require(service.revisionId)
      const params = rev.fields.map((f) => `<${f.type === 'gsm.imei' ? 'IMEI' : f.type === 'gsm.model' ? 'MODELID' : f.type === 'gsm.carrier' ? 'PROVIDERID' : f.type === 'gsm.serial' ? 'SN' : f.key.toUpperCase()}>${input[f.key] ?? ''}</${f.type === 'gsm.imei' ? 'IMEI' : f.type === 'gsm.model' ? 'MODELID' : f.type === 'gsm.carrier' ? 'PROVIDERID' : f.type === 'gsm.serial' ? 'SN' : f.key.toUpperCase()}>`).join('')
      const ref = rng.bool(0.6) ? `<REFERENCE>POS-${rng.int(100000, 999999)}</REFERENCE>` : ''
      handleDhru(rt, { username: acct.email, apiaccesskey: `${key.prefix}_${rng.hex(20)}`, action: 'placeimeiorder', parameters: `<PARAMETERS><ID>${service.code}</ID>${params}${ref}</PARAMETERS>` })
      const placed = repo.orders.recent(1)[0]
      if (placed && placed.accountId === accountId && rng.bool(0.7)) push({ t: it.t + rng.int(20, 600) * 1000, kind: 'poll', accountId, channel: 'dhru', serviceId: placed.ref })
      return
    }
    safely(() => placeOrder(ctx, { accountId, serviceId, input, channel, actor, payment: { mode: 'wallet' } }))
  }

  const execRead = () => {
    const spec = rng.pick([...byChannel('api'), ...byChannel('dhru')])
    if (spec.channels.includes('dhru') && rng.bool(0.4)) {
      const key = dhruKeyOf(spec.id)
      if (key) handleDhru(rt, { username: spec.email, apiaccesskey: `${key.prefix}_${rng.hex(20)}`, action: rng.pick(['accountinfo', 'imeiservicelist']) })
      return
    }
    const key = keyOf(spec.id)
    if (key) handleNative(rt, { method: 'GET', path: rng.pick(['/v1/services', '/v1/account', '/v1/account/transactions', '/v1/orders']), headers: { authorization: `Bearer ${key.prefix}_${rng.hex(24)}` }, ip: ipFor(key) })
  }

  const execError = () => {
    const kind = rng.weighted(['bad_imei', 'bad_key', 'scope', 'unknown_service'] as const, [55, 15, 15, 15])
    if (kind === 'bad_key') {
      handleNative(rt, { method: 'POST', path: '/v1/orders', headers: { authorization: `Bearer orx_live_${rng.hex(4)}_${rng.hex(20)}` }, body: { service: '4006', input: { imei: randomImei() } } })
      return
    }
    if (kind === 'scope') {
      const key = repo.apiKeys.require('key_bb_live1')
      handleNative(rt, { method: 'GET', path: '/v1/account', headers: { authorization: `Bearer ${key.prefix}_${rng.hex(24)}` } })
      return
    }
    const spec = rng.pick(byChannel('api'))
    const key = keyOf(spec.id)
    if (!key) return
    const bad = randomImei().slice(0, 14) + String((Number(randomImei().slice(-1)) + 3) % 10)
    handleNative(rt, { method: 'POST', path: '/v1/orders', headers: { authorization: `Bearer ${key.prefix}_${rng.hex(24)}`, 'idempotency-key': `idem_${rng.hex(16)}` }, body: kind === 'unknown_service' ? { service: '9999', input: { imei: randomImei() } } : { service: '4006', input: { imei: bad } } })
  }

  const execPoll = (it: PlanItem) => {
    if (it.channel === 'dhru') {
      const spec = accountSpec.get(it.accountId!)
      const key = dhruKeyOf(it.accountId!)
      if (spec && key) handleDhru(rt, { username: spec.email, apiaccesskey: `${key.prefix}_${rng.hex(20)}`, action: 'getimeiorder', parameters: `<PARAMETERS><ID>${it.serviceId}</ID></PARAMETERS>` })
      return
    }
    const key = keyOf(it.accountId!)
    if (key) handleNative(rt, { method: 'GET', path: `/v1/orders/${it.serviceId}`, headers: { authorization: `Bearer ${key.prefix}_${rng.hex(24)}` }, ip: ipFor(key) })
  }

  const sweep = (t: number) => {
    for (const o of repo.orders.filter((x) => x.status === 'needs_review' && !!x.review && new Date(x.review.openedAt).getTime() < t - 40 * MIN)) {
      safely(() => lookupSupplier(ctx, { orderId: o.id, actor: DANIEL }))
      if (o.status === 'needs_review') safely(() => confirmNotReceived(ctx, { orderId: o.id, reason: 'Supplier lookup found no record — safe to retry with the next offer', then: 'retry', actor: DANIEL }))
    }
  }

  const scripted = scriptScenarios(rt, now, { push, admin: { SARAH, DANIEL, OMAR }, memberOf, keyOf, dhruKeyOf, inputFor, fieldsOf })

  for (let i = 0; i < plan.length; i++) {
    const it = plan[i]!
    runJobs(rt, it.t)
    at(it.t)
    switch (it.kind) {
      case 'order':
        execOrder(it)
        break
      case 'read':
        execRead()
        break
      case 'error':
        execError()
        break
      case 'poll':
        execPoll(it)
        break
      case 'sweep':
        sweep(it.t)
        break
      case 'action':
        it.run?.()
        break
    }
  }
  runJobs(rt, now - 4 * MIN)
  at(now - 4 * MIN)
  // Operators already handled every other review; only the designated ones stay open.
  for (const o of repo.orders.filter((x) => x.status === 'needs_review' && !scripted.keepOpen.has(x.id))) {
    safely(() => lookupSupplier(ctx, { orderId: o.id, actor: DANIEL }))
    if (o.status === 'needs_review') safely(() => confirmNotReceived(ctx, { orderId: o.id, reason: 'Supplier lookup found no record — safe to retry with the next offer', then: 'retry', actor: DANIEL }))
  }
  runJobs(rt, now)
  at(now)

  /* ---------------- 6. Catalog sync — Supplier Alpha changes 4 minutes ago ---------------- */
  stageAlphaCatalogChanges(rt, now)
  for (const s of SUPPLIER_SPECS) if (s.id !== 'sup_alpha') {
    at(now - rng.int(10, 200) * MIN)
    runSync(ctx, s.id, SYSTEM, 'scheduled')
  }
  at(now - 4 * MIN)
  runSync(ctx, 'sup_alpha', SYSTEM, 'scheduled')
  at(now)

  /* ---------------- 7. Calibration ---------------- */
  calibrate(rt, now, accountSpec, OMAR)

  /* ---------------- 8. Health samples ---------------- */
  for (const s of repo.suppliers.all()) {
    for (let k = 48; k >= 0; k--) {
      const t = now - k * 30 * MIN
      const failing =
        (s.id === 'sup_epsilon' && t > now - 2 * HOUR) ||
        (s.id === 'sup_eta' && t > now - 25 * MIN) ||
        (s.id === 'sup_iota' && t > now - 40 * MIN) ||
        (s.id === 'sup_theta' && t > now - 45 * MIN && t < now - 15 * MIN) ||
        (s.id === 'sup_delta' && rng.bool(0.12))
      repo.healthSamples.insert({ id: `hs_${s.id}_${k}`, supplierId: s.id, at: new Date(t).toISOString(), ok: !failing, latencyMs: failing ? s.timeoutMs : Math.round(rng.normal(s.profile.latencyMs, s.profile.latencyMs * 0.25)), note: failing ? (s.id === 'sup_epsilon' ? 'Authentication failed' : s.id === 'sup_iota' ? 'Maintenance (503)' : 'Connection refused') : 'OK' })
    }
  }

  /* ---------------- 9. Provider API demo — Global GSM Provider ---------------- */
  seedProviderApiDemo(rt, now, SARAH)

  rt.scenarios = scripted.refs()
  clock.set(null)
  rt.live = true
  rt.seededAt = now
}

/* ------------------------------------------------------------------------- */
/*  Scenarios A–L                                                            */
/* ------------------------------------------------------------------------- */
interface ScenarioDeps {
  push: (it: PlanItem) => void
  admin: { SARAH: Actor; DANIEL: Actor; OMAR: Actor }
  memberOf: (accountId: string, prefer?: string[]) => Actor
  keyOf: (accountId: string) => { prefix: string; ipAllowlist: string[] } | undefined
  dhruKeyOf: (accountId: string) => { prefix: string; ipAllowlist: string[] } | undefined
  inputFor: (fields: FieldDef[], imei?: string) => Record<string, string>
  fieldsOf: (serviceId: string) => FieldDef[]
}

function scriptScenarios(rt: Runtime, now: number, deps: ScenarioDeps) {
  const { repo, ctx, rng } = rt
  const refs: Record<string, string> = {}
  const tokens: Record<string, string> = {}
  const keepOpen = new Set<string>()
  const action = (msAgo: number, run: () => void) => deps.push({ t: now - msAgo, kind: 'action', run })
  const force = (supplierId: string, orderRef: string, behaviour: SimBehaviour, received?: boolean) => setBehaviour(rt.sim, supplierId, behaviour, 1, ctx.clock.iso(), { orderRef, received })
  let placedRef = ''
  /** The order created by the last scenario helper call. */
  const latest = () => repo.orders.byRef(placedRef)!
  const tag = (letter: string) => {
    const o = latest()
    o.scenario = letter
    refs[letter] = o.id
    return o
  }
  const ensureFunds = (accountId: string, amount: number) => {
    const bal = walletBalance(ctx, accountId)
    if (bal.spendable >= usd(amount)) return
    const intent = createTopUp(ctx, { accountId, amount: usd(Math.ceil(amount - bal.spendable / 1e6) + 50), method: 'card', actor: deps.memberOf(accountId, ['finance', 'owner']) })
    completePayment(ctx, { intentId: intent.id, outcome: 'succeed' })
  }
  /** Place via the native API with targeted supplier behaviour. */
  const apiOrder = (accountId: string, code: string, input: Record<string, string>, idem?: string) => {
    const key = deps.keyOf(accountId)!
    ensureFunds(accountId, 40)
    const res = handleNative(rt, { method: 'POST', path: '/v1/orders', headers: { authorization: `Bearer ${key.prefix}_${rng.hex(24)}`, ...(idem ? { 'idempotency-key': idem } : {}) }, body: { service: code, input }, ip: ipFor(key) })
    const ref = (res.body as { id?: string }).id
    if (res.status < 300 && ref) placedRef = ref
    else if (res.status >= 400 && res.status !== 409) console.warn('[seed] scenario API order failed', accountId, code, res.body)
  }
  const portalOrder = (accountId: string, serviceId: string, input: Record<string, string>) => {
    ensureFunds(accountId, 40)
    placedRef = placeOrder(ctx, { accountId, serviceId, input, channel: 'portal', actor: deps.memberOf(accountId), payment: { mode: 'wallet' } }).order.ref
  }
  const dhruOrder = (accountId: string, code: string, input: Record<string, string>) => {
    const key = deps.dhruKeyOf(accountId)!
    ensureFunds(accountId, 40)
    const spec = repo.accounts.require(accountId)
    const params = Object.entries(input).map(([k, v]) => (k === 'imei' ? `<IMEI>${v}</IMEI>` : k === 'model' ? `<MODELID>${v}</MODELID>` : `<${k.toUpperCase()}>${v}</${k.toUpperCase()}>`)).join('')
    const res = handleDhru(rt, { username: spec.email, apiaccesskey: `${key.prefix}_${rng.hex(20)}`, action: 'placeimeiorder', parameters: `<PARAMETERS><ID>${code}</ID>${params}</PARAMETERS>` })
    const ref = (res.body as { SUCCESS?: { REFERENCEID?: string }[] }).SUCCESS?.[0]?.REFERENCEID
    if (ref) placedRef = ref
    else console.warn('[seed] scenario DHRU order failed', accountId, code, JSON.stringify(res.body))
  }
  const imei = () => withLuhn(`35${rng.int(1000000, 9999999)}${rng.int(10000, 99999)}`)

  /* G — verification on an ABC GSM unlock code from yesterday */
  action(28 * HOUR, () => {
    portalOrder('acc_abcgsm', 'svc_4040', { imei: imei(), model: 'SM-A546B' })
    force('sup_beta', tag('G').ref, 'success')
  })
  action(3 * HOUR, () => {
    const o = repo.orders.require(refs.G!)
    if (o.status === 'completed') openVerification(ctx, { orderId: o.id, reason: 'code_not_working', message: 'Code does not work — the phone says “Network unlock unsuccessful”.', actor: deps.memberOf('acc_abcgsm', ['orderer']) })
  })

  /* K — partial refund (Insure-a-Phone) */
  action(6 * HOUR, () => {
    portalOrder('acc_insure', 'svc_4007', { imei: imei() })
    force('sup_gamma', tag('K').ref, 'success')
  })
  action(5 * HOUR, () => {
    const o = repo.orders.require(refs.K!)
    if (o.financialStatus === 'captured') refundOrder(ctx, { orderId: o.id, amount: roundTo(times(o.price.amount, 0.4), usd(0.01), 'down'), destination: 'wallet', reason: 'Result delivered after the agreed SLA — goodwill partial refund (40%)', actor: deps.admin.OMAR, idempotencyKey: 'scenario-k-partial' })
  })

  /* Needs-review set (7 open UNKNOWN outcomes) */
  action(4 * HOUR + 30 * MIN, () => {
    dhruOrder('acc_asiagsm', '4044', { imei: imei(), model: 'E5577s-321' })
    force('sup_delta', latest().ref, 'timeout', false)
    keepOpen.add(latest().id)
  })
  action(3 * HOUR, () => {
    apiOrder('acc_checkmyimei', '4024', { imei: imei() })
    force('sup_gamma', latest().ref, 'unknown', true)
    keepOpen.add(latest().id)
  })
  action(2 * HOUR + 10 * MIN, () => {
    apiOrder('acc_mobilehub', '4006', { imei: imei() })
    force('sup_gamma', latest().ref, 'timeout', true)
    keepOpen.add(latest().id)
  })
  action(1 * HOUR + 45 * MIN, () => {
    portalOrder('acc_recell', 'svc_4012', { imei: imei() })
    force('sup_gamma', latest().ref, 'unknown', true)
    keepOpen.add(latest().id)
  })
  action(1 * HOUR + 20 * MIN, () => {
    const r = placeOrder(ctx, { accountId: 'acc_r05', serviceId: 'svc_4040', input: { imei: imei(), model: 'SM-S911B' }, channel: 'storefront', actor: { type: 'member', id: 'acc_r05', name: repo.accounts.require('acc_r05').name }, payment: { mode: 'external', method: 'card' }, tracking: true })
    force('sup_beta', r.order.ref, 'unknown', false)
    keepOpen.add(r.order.id)
    ctx.scheduler.schedule('payment.settle', { intentId: r.paymentIntentId!, outcome: 'succeed' }, ctx.clock.now() + 40_000)
  })
  action(55 * MIN, () => {
    dhruOrder('acc_istanbul', '4008', { imei: imei() })
    force('sup_gamma', latest().ref, 'timeout', true)
    keepOpen.add(latest().id)
  })

  /* E — Epsilon auth failure → failover (Movil Express via DHRU) */
  action(1 * HOUR + 50 * MIN, () => {
    dhruOrder('acc_movil', '4043', { imei: imei(), model: 'ZTE Blade A52' })
    force('sup_beta', tag('E').ref, 'success')
  })

  /* F — negative margin: Platinum contract price below Gamma's new cost → margin guard */
  action(1 * HOUR, () => {
    apiOrder('acc_mobilehub', '4011', { imei: imei() })
    force('sup_beta', tag('F').ref, 'success')
  })

  /* Theta: five refused connections → circuit opens → half-open after cooldown */
  for (let k = 0; k < 5; k++)
    action(42 * MIN - k * 3 * MIN, () => {
      portalOrder('acc_cellpoint', 'svc_4017', { imei: imei() })
      const o = latest()
      force('sup_theta', o.ref, 'network_error')
      force('sup_beta', o.ref, 'success')
    })

  /* B — Alpha rejects (failover-safe) → Beta succeeds (ABC GSM portal) */
  action(50 * MIN, () => {
    portalOrder('acc_abcgsm', 'svc_4003', { imei: imei() })
    const o = tag('B')
    force('sup_alpha', o.ref, 'rejected_safe')
    force('sup_beta', o.ref, 'success')
  })

  /* ABC GSM in-flight async order ($9.00 held) */
  action(45 * MIN, () => {
    portalOrder('acc_abcgsm', 'svc_4040', { imei: imei(), model: 'SM-S918B' })
    force('sup_beta', latest().ref, 'success')
  })

  /* C — Alpha times out → UNKNOWN → needs_review (ABC GSM API, $18.00 held) */
  action(38 * MIN, () => {
    apiOrder('acc_abcgsm', '4037', { imei: imei() }, 'abc-pos-20261004-7781')
    force('sup_alpha', tag('C').ref, 'timeout', true)
    keepOpen.add(refs.C!)
  })

  /* D — Zeta insufficient funds → failover to Gamma */
  action(35 * MIN, () => {
    portalOrder('acc_recell', 'svc_4031', { imei: imei() })
    const o = tag('D')
    force('sup_zeta', o.ref, 'insufficient_funds')
    force('sup_gamma', o.ref, 'success')
  })

  /* A — guest storefront order: iPhone 15 Carrier Check → T-Mobile · Clean */
  action(25 * MIN, () => {
    const guest = ensureGuestAccount(ctx, 'maya.l@mail.example', 'tier_retail')
    const r = placeOrder(ctx, { accountId: guest.id, serviceId: 'svc_4001', input: { imei: DEMO_IMEIS[0]!.imei }, channel: 'storefront', actor: { type: 'guest', id: guest.id, name: guest.email }, payment: { mode: 'external', method: 'card' }, tracking: true })
    r.order.scenario = 'A'
    refs.A = r.order.id
    tokens.A = r.order.trackingToken!
    force('sup_alpha', r.order.ref, 'success')
    ctx.scheduler.schedule('payment.settle', { intentId: r.paymentIntentId!, outcome: 'succeed' }, ctx.clock.now() + 38_000)
  })

  /* Eta: refused connections → circuit opens */
  for (let k = 0; k < 5; k++)
    action(22 * MIN - k * 3 * MIN, () => {
      apiOrder('acc_techrepair', '4041', { imei: imei(), model: 'Moto G84' })
      const o = latest()
      force('sup_eta', o.ref, 'network_error')
      force('sup_beta', o.ref, 'success')
    })

  /* H + I — signed-in customer pays with PayPal; the gateway sends its webhook twice */
  action(18 * MIN, () => {
    const r = placeOrder(ctx, { accountId: 'acc_r01', serviceId: 'svc_4007', input: { imei: imei() }, channel: 'storefront', actor: { type: 'member', id: 'acc_r01', name: 'Liam Carter' }, payment: { mode: 'external', method: 'paypal' }, tracking: true })
    r.order.scenario = 'H'
    refs.H = r.order.id
    tokens.H = r.order.trackingToken!
    force('sup_gamma', r.order.ref, 'success')
    ctx.scheduler.schedule('payment.settle', { intentId: r.paymentIntentId!, outcome: 'succeed' }, ctx.clock.now() + 35_000)
  })
  action(16 * MIN, () => {
    const o = repo.orders.require(refs.H!)
    if (o.paymentIntentId) {
      replayGatewayWebhook(ctx, o.paymentIntentId)
      refs.I = o.id
    }
  })

  /* J — API reseller retries with the same Idempotency-Key (and once with a different body) */
  action(15 * MIN, () => {
    const input = { imei: withLuhn('35391810652345'.slice(0, 2) + String(rng.int(100000000000, 999999999999)).slice(0, 12)) }
    apiOrder('acc_mobilehub', '4006', input, 'mh-batch-20261004-0042')
    tag('J')
  })
  action(15 * MIN - 4000, () => apiOrder('acc_mobilehub', '4006', repo.orders.require(refs.J!).input, 'mh-batch-20261004-0042'))
  action(15 * MIN - 9000, () => apiOrder('acc_mobilehub', '4006', { imei: imei() }, 'mh-batch-20261004-0042'))

  return {
    keepOpen,
    refs(): ScenarioRef[] {
      const o = (k: string) => (refs[k] ? repo.orders.get(refs[k]!) : undefined)
      const link = (k: string, label = 'Open order') => (o(k) ? [{ label: `${label} ${o(k)!.ref}`, href: `/admin/orders/${o(k)!.id}` }] : [])
      return [
        { id: 'A', title: 'Normal successful IMEI check', description: 'Guest buys an iPhone 15 Carrier Check on the storefront, pays by card, gets “T-Mobile · Clean”.', links: [...link('A'), ...(tokens.A ? [{ label: 'Customer tracking page', href: `/site/track/${tokens.A}` }] : [])] },
        { id: 'B', title: 'Supplier A rejects → Supplier B succeeds', description: 'Alpha returns a failover-safe rejection; ORVEX fails over to Beta under the margin guard.', links: link('B') },
        { id: 'C', title: 'Timeout → UNKNOWN → Needs Review', description: 'Alpha never answered. Failover is blocked, $18.00 stays held, the supplier balance shows −$11.00 drift.', links: [...link('C'), { label: 'Needs Review queue', href: '/admin/orders?status=needs_review' }, { label: 'Alpha reconciliation', href: '/admin/finance/reconciliation?supplier=sup_alpha' }] },
        { id: 'D', title: 'Low supplier balance', description: 'Zeta Device Data is below its threshold; an order failed over after “insufficient credit”.', links: [...link('D'), { label: 'Zeta supplier', href: '/admin/suppliers/sup_zeta' }] },
        { id: 'E', title: 'Supplier authentication failure', description: 'Epsilon rotated its API keys; attempts are not accepted and route to the next offer.', links: [...link('E'), { label: 'Epsilon supplier', href: '/admin/suppliers/sup_epsilon' }] },
        { id: 'F', title: 'Negative margin warning', description: 'Platinum contract price ($0.40) is below Gamma’s new cost ($0.46). The margin guard skips Gamma.', links: [...link('F'), { label: 'Motorola IMEI Check pricing', href: '/admin/services/svc_4011?tab=pricing' }] },
        { id: 'G', title: 'Verification request (“code does not work”)', description: 'ABC GSM reports an unlock code that failed. Recheck, ask the supplier, refund or reject.', links: [...link('G'), { label: 'Verification requests', href: '/admin/verifications' }] },
        { id: 'H', title: 'Payment, then order', description: 'A signed-in customer pays with PayPal; the confirmed payment funds the wallet, the hold is created and the order is queued.', links: [...link('H'), ...(tokens.H ? [{ label: 'Customer tracking page', href: `/site/track/${tokens.H}` }] : [])] },
        { id: 'I', title: 'Duplicated payment webhook', description: 'The gateway delivered payment.succeeded twice — the second was recorded and ignored; the wallet was funded once.', links: [{ label: 'Inbound webhooks', href: '/admin/developer/webhooks?tab=inbound' }, ...link('H', 'Order')] },
        { id: 'J', title: 'Same Idempotency-Key sent twice', description: 'MobileHub retried POST /v1/orders with the same key: one order, one charge. A different body with that key got 409.', links: [...link('J'), { label: 'API logs', href: '/admin/developer/logs?search=mh-batch-20261004-0042' }] },
        { id: 'K', title: 'Partial refund', description: 'Insure-a-Phone received 40% back to its wallet; the order stays completed, financial status partially refunded.', links: link('K') },
        { id: 'L', title: 'Service unavailable — all offers unhealthy', description: 'Alcatel / TCL Unlock Code: Epsilon (auth error) and Eta (circuit open) are its only offers. The storefront shows it as unavailable.', links: [{ label: 'Alcatel / TCL service', href: '/admin/services/svc_4042' }, { label: 'On the storefront', href: '/site/services/alcatel-tcl-unlock-code-nck' }] },
      ]
    },
  }
}

/* ------------------------------------------------------------------------- */
/*  Supplier Alpha catalog changes (12 new, 7 price, 2 removed, 4 fields, 3 warnings) */
/* ------------------------------------------------------------------------- */
function stageAlphaCatalogChanges(rt: Runtime, _now: number) {
  const remote = remoteOf(rt.env, 'sup_alpha')
  const local = rt.repo.products.filter((p) => p.supplierId === 'sup_alpha' && p.status === 'available')
  const byExt = (ext: string) => remote.catalog.find((r) => r.externalId === ext)!
  const prod = (id: string) => rt.repo.products.require(id)
  // 7 price changes — iPhone 15 Carrier Check first ($0.72 → $0.81).
  const priceTargets: [string, number][] = [['sp_alpha_4001', 0.81], ['sp_alpha_4002', 0.92], ['sp_alpha_4004', 0.55], ['sp_alpha_4016', 0.37], ['sp_alpha_4028', 0.41], ['sp_alpha_4038', 8.9], ['sp_alpha_4045', 9.6]]
  for (const [id, cost] of priceTargets) if (rt.repo.products.get(id)) byExt(prod(id).externalId).cost = usd(cost)
  // 4 field changes (supplier now also requires the model).
  for (const id of ['sp_alpha_4024', 'sp_alpha_4009', 'sp_alpha_4012', 'sp_alpha_4020']) if (rt.repo.products.get(id)) {
    const r = byExt(prod(id).externalId)
    if (!r.fields.includes('MODELID')) r.fields = [...r.fields, 'MODELID']
  }
  // 3 renames (warnings).
  const renames: [string, string][] = [['sp_alpha_4013', 'Trade-in Pro Bundle (Blacklist + Carrier + iCloud status)'], ['sp_alpha_4014', 'Apple Sold-by & Replacement Info'], ['sp_alpha_4053', 'Apple Serial → Device Profile']]
  for (const [id, name] of renames) if (rt.repo.products.get(id)) byExt(prod(id).externalId).name = name
  // 2 removed: one mapped (iPhone 12 & Older), one unmapped.
  const removeIds = ['sp_alpha_4005', local.find((p) => p.id.startsWith('sp_alpha_x'))?.id].filter(Boolean) as string[]
  const removedExt = new Set(removeIds.map((id) => prod(id).externalId))
  remote.catalog = remote.catalog.filter((r) => !removedExt.has(r.externalId))
  // 12 new products.
  const newOnes = ['iPhone 17 Carrier Check', 'iPhone 17 Pro Carrier Check', 'Galaxy S25 Carrier Check', 'Pixel 9 Carrier Check', 'iPad Activation Lock Status', 'Apple Watch Carrier Check', 'Canada Carrier Lookup', 'Australia Network Check', 'eSIM Transfer Eligibility', 'Device Insurance Status', 'Samsung KG Lock Status', 'Xiaomi Region Check']
  newOnes.forEach((name, i) => remote.catalog.push({ externalId: String(2400 + i * 7), name, groupName: 'New in 2026', cost: usd(+(0.4 + i * 0.07).toFixed(2)), fields: ['IMEI'], processingHint: 'Instant' }))
}

/* ------------------------------------------------------------------------- */
/*  Provider API demo — Global GSM Provider (100-service catalog)            */
/* ------------------------------------------------------------------------- */
/**
 * Runs after everything else (own RNG, offers appended at the lowest priority)
 * so the calibrated demo script above is untouched. The catalog was imported
 * 12 days ago, 22 products were mapped as fallback offers, scheduled syncs ran,
 * and the provider has since changed its catalog: the next manual sync
 * discovers 2 new · 4 changed · 1 removed (95 unchanged).
 */
function seedProviderApiDemo(rt: Runtime, now: number, operator: Actor) {
  const { ctx, repo, clock } = rt
  const spec = GLOBAL_PROVIDER_SPEC
  const rng = createRng(7301)
  const iso = (t: number) => new Date(t).toISOString()
  const connectedAt = now - spec.connectedDaysAgo * DAY
  const lastScheduled = now - 2 * HOUR - 12 * MIN

  const s = buildSupplier(spec, now)
  repo.suppliers.insert(s)
  clock.set(connectedAt)
  audit(ctx, { actor: operator, action: 'supplier.connected', target: { type: 'supplier', id: s.id, label: s.name }, summary: `Connected ${s.name} (${s.driver})`, severity: 'notice', permission: 'suppliers.manage' })
  const remote = remoteOf(rt.env, s.id)
  remote.balance = spec.targetExpected
  remote.catalog = GLOBAL_CATALOG.map((i) => toRemoteProduct(i, s.driver))
  repo.driverCalls.insert(ctx.drivers.get(s.driver).testConnection(s).call)
  supplierTopUp(ctx, { supplierId: s.id, amount: spec.targetExpected, actor: operator, idempotencyKey: `seed-supplier-topup-${s.id}`, note: `Opening prepaid balance · ${s.name}`, at: connectedAt + 10 * MIN })

  // Initial catalog import: every remote service becomes a supplier product (source data, not a service).
  const importAt = connectedAt + 20 * MIN
  clock.set(importAt)
  const imported = ctx.drivers.get(s.driver).syncCatalog(s, [])
  repo.driverCalls.insert(imported.call)
  for (const i of GLOBAL_CATALOG) {
    repo.products.insert({ id: `sp_global_${i.externalId}`, supplierId: s.id, externalId: i.externalId, name: i.name, groupName: i.group, cost: usd(i.cost), previousCost: null, status: 'available', remoteFields: [...i.fields], processingHint: i.processing, firstSeenAt: iso(importAt), lastSeenAt: iso(lastScheduled), costChangedAt: null })
  }
  repo.syncRuns.insert({ id: ctx.ids.id('sync'), supplierId: s.id, trigger: 'manual', startedAt: iso(importAt), finishedAt: iso(importAt + imported.latencyMs), status: 'applied', remoteProducts: GLOBAL_CATALOG.length, counts: { new: GLOBAL_CATALOG.length, price: 0, removed: 0, fields: 0, warning: 0 }, error: null })
  s.lastSyncAt = iso(importAt + imported.latencyMs)
  audit(ctx, { actor: operator, action: 'catalog.imported', target: { type: 'supplier', id: s.id, label: s.name }, summary: `Initial catalog import — ${GLOBAL_CATALOG.length} supplier products`, permission: 'suppliers.manage' })

  // Mapping: selected products become offers on existing ORVEX services (after the primary suppliers).
  clock.set(connectedAt + DAY)
  for (const i of GLOBAL_CATALOG) {
    const svc = i.mapTo ? repo.services.get(i.mapTo) : undefined
    if (!svc) continue
    const fields = repo.revisions.require(svc.revisionId).fields
    addOffer(ctx, { serviceId: svc.id, supplierProductId: `sp_global_${i.externalId}`, fieldMapping: Object.fromEntries(fields.filter((f) => i.fields.includes(f.key)).map((f) => [f.key, f.key])), maxCost: null, actor: operator })
  }

  // Scheduled syncs since then — no changes.
  for (const t of [9 * DAY, 6 * DAY, 3 * DAY, 1 * DAY].map((d) => now - d + rng.int(0, 6) * HOUR).concat(lastScheduled)) {
    clock.set(t)
    runSync(ctx, s.id, SYSTEM, 'scheduled')
  }

  // The provider changed its catalog after the last scheduled sync.
  const byExt = new Map(remote.catalog.map((r) => [r.externalId, r]))
  for (const [ext, cost] of GLOBAL_SYNC_DELTA.priced) byExt.get(ext)!.cost = usd(cost)
  for (const [ext, fields] of GLOBAL_SYNC_DELTA.fields) byExt.get(ext)!.fields = [...fields]
  remote.catalog = remote.catalog.filter((r) => !GLOBAL_SYNC_DELTA.removed.includes(r.externalId))
  remote.catalog.push(...GLOBAL_SYNC_DELTA.added.map((i) => toRemoteProduct(i, s.driver)))

  s.reportedBalance = remote.balance
  s.balanceCheckedAt = iso(now - 6 * MIN)
  s.auth.checkedAt = iso(now - 40 * MIN)
  for (let k = 48; k >= 0; k--) {
    repo.healthSamples.insert({ id: `hs_${s.id}_${k}`, supplierId: s.id, at: iso(now - k * 30 * MIN), ok: true, latencyMs: Math.round(rng.normal(s.profile.latencyMs, s.profile.latencyMs * 0.2)), note: 'OK' })
  }
  clock.set(now)
}

/* ------------------------------------------------------------------------- */
/*  Calibration to the demo script                                           */
/* ------------------------------------------------------------------------- */
function calibrate(rt: Runtime, now: number, specs: Map<string, AccountSpec>, finance: Actor) {
  const { ctx, repo, rng, clock } = rt
  // Suppliers: expected balance = target; reported = expected − unknown received costs + extra drift.
  for (const spec of SUPPLIER_SPECS) {
    const s = repo.suppliers.require(spec.id)
    const d = supplierDrift(ctx, s)
    const delta = (spec.targetExpected + d.inFlight - d.ledger) as Micros
    if (delta > 0) {
      const parts = [0.55, 0.25, 0.2]
      let posted = 0
      parts.forEach((p, i) => {
        const amount = (i === parts.length - 1 ? delta - posted : Math.round((delta * p) / 10_000) * 10_000) as Micros
        posted += amount
        supplierTopUp(ctx, { supplierId: s.id, amount, actor: finance, idempotencyKey: `seed-supplier-topup-${s.id}-${i}`, note: i === 0 ? `Opening prepaid balance · ${s.name}` : `Prepaid top-up · ${s.name}`, at: now - (29 - i * 10) * 86400_000 })
      })
    }
    const remote = remoteOf(rt.env, s.id)
    const unknownReceived = Object.values(remote.orders)
      .filter((ro) => {
        const o = repo.orders.get(ro.orderId)
        return o?.status === 'needs_review' && o.attempts.some((a) => a.supplierId === s.id && a.state === 'unknown') && ro.charged
      })
      .reduce((a, ro) => a + ro.cost, 0)
    remote.balance = (spec.targetExpected - unknownReceived + spec.extraDrift) as Micros
    s.reportedBalance = remote.balance
    s.balanceCheckedAt = new Date(now - rng.int(1, 9) * 60_000).toISOString()
  }
  // Accounts: final top-up so wallets land on the demo script values (only ever adds money).
  for (const [id, spec] of specs) {
    if (spec.targetAvailable == null) continue
    const acct = repo.accounts.get(id)
    if (!acct || acct.status !== 'active') continue
    const bal = walletBalance(ctx, id)
    const delta = usd(spec.targetAvailable) - bal.available
    if (delta <= 0) continue
    clock.set(now - rng.int(150, 420) * 60_000)
    if (delta < usd(5)) {
      // Below the bank-transfer minimum: a small goodwill credit (audited ledger adjustment) instead.
      adjustAccountWallet(ctx, { accountId: id, amount: delta as Micros, reason: 'Goodwill credit — delayed order compensation', actor: finance, idempotencyKey: `seed-goodwill-${id}` })
      continue
    }
    const intent = createTopUp(ctx, { accountId: id, amount: delta as Micros, method: 'bank_transfer', actor: { type: 'member', id: `mem_${id.replace('acc_', '')}_1`, name: acct.contactName } })
    confirmBankTransfer(ctx, { intentId: intent.id, actor: finance })
  }
  clock.set(now)
  for (const a of repo.accounts.filter((x) => x.lowBalanceAlert != null && x.status === 'active')) {
    const b = walletBalance(ctx, a.id)
    if (b.available < a.lowBalanceAlert!) notify(ctx, { template: 'account.low_balance', accountId: a.id, vars: { balance: formatMoney(b.available) } })
  }
}
